#' one lines, that will be used in the bookdown report of the results from
#' {testthat}. This line can be more than 80 characters.

# default_population_edges ----
## Setup ----
# No setup required.

## IO correctness ----
test_that("`default_population_edges()` works with correct inputs", {
  #' @description Test that whole-number fleet edges give 1-unit population bins up to the top fleet edge, then 1 more.
  expect_equal(
    object = FIMS:::default_population_edges(list(seq(0, 10, by = 2))),
    expected = 0:11
  )
})

## Edge handling ----
test_that("`default_population_edges()` returns correct outputs for edge cases", {
  # 20 fleet bins 1.1 units wide end at 22 plus rounding error.
  fleet_edges <- list(c(0, 1.1 * (1:20)))
  #' @description Test that `default_population_edges()` stops the grid at 22 when the top fleet edge is 22 plus rounding error, then adds 1 plus-group bin.
  expect_equal(
    object = FIMS:::default_population_edges(fleet_edges),
    expected = 0:23
  )
})

## Error handling ----
test_that("`default_population_edges()` returns correct error messages", {
  #' @description Test that `default_population_edges()` errors when a fleet has length bins narrower than the 1-unit population bins.
  expect_error(
    object = FIMS:::default_population_edges(
      list(fleet1 = seq(0, 10, by = 0.5))
    ),
    regexp = "narrower than 1 length unit"
  )
})

# edges_from_lower_edges ----
## Setup ----
# No setup required.

## IO correctness ----
test_that("`edges_from_lower_edges()` works with correct inputs", {
  #' @description Test that `edges_from_lower_edges()` gives the last bin the same width as the one before it.
  expect_equal(
    object = FIMS:::edges_from_lower_edges(c(0, 2, 5)),
    expected = c(0, 2, 5, 8)
  )
})

## Edge handling ----
# No edge cases to test.

## Error handling ----
test_that("`edges_from_lower_edges()` returns correct error messages", {
  #' @description Test that `edges_from_lower_edges()` errors when given fewer than 2 lower edges.
  expect_error(
    object = FIMS:::edges_from_lower_edges(5, fleet = "fleet1"),
    regexp = "at least 2"
  )
})
